(2,7,13,'students=[]\r\nn=int(input(\"How many names you want to give?=>\"))\r\n\r\nfor i in range(n):\r\n    name=input(\"Enter the name of student=>\")\r\n    students.append(name)\r\nprint(students)\r\n\r\nstudents.sort()\r\nprint(students)\r\n\r\nprint(\"Total number of Students\",len(students))\r\nprint(students)\r\n\r\n\r\nprint(students[-3:])',0,0,'2026-01-30 12:37:30','2026-01-30 12:37:30'),
(3,11,14,'class foreachloop1 \r\n{\r\n    public static void main(String[] args)\r\n	{\r\n\r\n        int[] marks = {125, 132, 95, 116, 110};\r\n        int max = findMax(marks);\r\n        int min = findMin(marks);\r\n\r\n        System.out.println(max);\r\n        System.out.println(min);\r\n    }\r\n	\r\n    static int findMax(int[] arr)\r\n	{\r\n        int maximum = arr[0];\r\n        for (int value : arr)\r\n		{\r\n            if (value > maximum) \r\n			{\r\n                maximum = value;\r\n            }\r\n			\r\n			\r\n        }\r\n        return maximum;\r\n    }\r\n	\r\n	static int findMin(int[] arr)\r\n	{\r\n        int minimum = arr[0];\r\n        for (int value : arr)\r\n		{\r\n            if (value < minimum) \r\n			{\r\n                minimum = value;\r\n            }\r\n			\r\n			\r\n        }\r\n        return minimum;\r\n    }\r\n}',1,1,'2026-01-30 13:24:22','2026-01-30 14:48:36'),
(4,14,1,'import java.util.Scanner;\r\nclass Palindrome {\r\n    public static void main(String[] args) {\r\n        int number;\r\n        Scanner scanner = new Scanner(System.in);\r\n        System.out.print(\"Enter a number: \");\r\n        number = scanner.nextInt();\r\n        int originalNumber = number;\r\n        int reversedNumber = 0;\r\n        while (number != 0) {\r\n            int digit = number % 10;\r\n            reversedNumber = reversedNumber * 10 + digit;\r\n            number /= 10;\r\n        }\r\n        if (originalNumber == reversedNumber) {\r\n            System.out.println(originalNumber + \" is a palindrome.\");\r\n        } else {\r\n            System.out.println(originalNumber + \" is not a palindrome.\");\r\n        }\r\n    }\r\n}',0,1,'2026-02-03 05:25:17','2026-02-03 05:25:24'),
(5,15,1,'interface Shape {\r\n    double calculateArea();\r\n}\r\n\r\nclass Rectangle implements Shape {\r\n    private final double length;\r\n    private final double width;\r\n\r\n    public Rectangle(double length, double width) {\r\n        this.length = length;\r\n        this.width = width;\r\n    }\r\n\r\n    @Override\r\n    public double calculateArea() {\r\n        return length * width;\r\n    }\r\n}\r\n\r\nclass Circle implements Shape {\r\n    private final double radius;\r\n\r\n    public Circle(double radius) {\r\n        this.radius = radius;\r\n    }\r\n\r\n    @Override\r\n    public double calculateArea() {\r\n        return Math.PI * radius * radius;\r\n    }\r\n}\r\n\r\nclass Triangle implements Shape {\r\n    private final double base;\r\n    private final double height;\r\n\r\n    public Triangle(double base, double height) {\r\n        this.base = base;\r\n        this.height = height;\r\n    }\r\n\r\n    @Override\r\n    public double calculateArea() {\r\n        return 0.5 * base * height;\r\n    }\r\n}\r\n\r\npublic class ShapeDemo {\r\n    public static void main(String[] args) {\r\n        Shape rectangle = new Rectangle(10, 5);\r\n        Shape circle = new Circle(7);\r\n        Shape triangle = new Triangle(8, 6);\r\n\r\n        System.out.println(\"Rectangle area: \" + rectangle.calculateArea());\r\n        System.out.println(\"Circle area: \" + circle.calculateArea());\r\n        System.out.println(\"Triangle area: \" + triangle.calculateArea());\r\n    }\r\n}',0,0,'2026-02-03 05:31:28','2026-02-03 05:31:28'),
(6,16,1,'abstract class Student {\r\n    protected final String name;\r\n    protected final String id;\r\n    protected final int age;\r\n    protected final String address;\r\n\r\n    public Student(String name, String id, int age, String address) {\r\n        this.name = name;\r\n        this.id = id;\r\n        this.age = age;\r\n        this.address = address;\r\n    }\r\n\r\n    public abstract String findGrade(double percent);\r\n}\r\n\r\nclass Grade extends Student {\r\n    public Grade(String name, String id, int age, String address) {\r\n        super(name, id, age, address);\r\n    }\r\n\r\n    @Override\r\n    public String findGrade(double percent) {\r\n        if (percent < 0 || percent > 100) {\r\n            return \"Invalid percent\";\r\n        }\r\n        if (percent >= 90) {\r\n            return \"A\";\r\n        }\r\n        if (percent >= 80) {\r\n            return \"B\";\r\n        }\r\n        if (percent >= 70) {\r\n            return \"C\";\r\n        }\r\n        if (percent >= 60) {\r\n            return \"D\";\r\n        }\r\n        return \"F\";\r\n    }\r\n}\r\n\r\npublic class StudentGradeTest {\r\n    public static void main(String[] args) {\r\n        java.util.Scanner scanner = new java.util.Scanner(System.in);\r\n\r\n        System.out.print(\"Enter name: \");\r\n        String name = scanner.nextLine().trim();\r\n\r\n        System.out.print(\"Enter ID: \");\r\n        String id = scanner.nextLine().trim();\r\n\r\n        System.out.print(\"Enter age: \");\r\n        int age = Integer.parseInt(scanner.nextLine().trim());\r\n\r\n        System.out.print(\"Enter address: \");\r\n        String address = scanner.nextLine().trim();\r\n\r\n        System.out.print(\"Enter percent (0-100): \");\r\n        double percent = Double.parseDouble(scanner.nextLine().trim());\r\n\r\n        Grade grad = new Grade(name, id, age, address);\r\n        String grade = grad.findGrade(percent);\r\n\r\n        System.out.println(\"Name: \" + grad.name);\r\n        System.out.println(\"ID: \" + grad.id);\r\n        System.out.println(\"Age: \" + grad.age);\r\n        System.out.println(\"Address: \" + grad.address);\r\n        System.out.println(\"Percent: \" + percent);\r\n        System.out.println(\"Grade: \" + grade);\r\n    }\r\n}',0,1,'2026-02-03 05:43:35','2026-02-03 05:43:42'),
(7,29,1,'#include <stdio.h>\r\n\r\nstruct item\r\n{\r\n    int item_code;\r\n    char name[30];\r\n    int quantity;\r\n};\r\n\r\nint main()\r\n{\r\n    struct item i;\r\n\r\n    // Taking input\r\n    printf(\"Enter Item Code: \");\r\n    scanf(\"%d\", &i.item_code);\r\n\r\n    printf(\"Enter Item Name: \");\r\n    scanf(\"%s\", i.name);\r\n\r\n    printf(\"Enter Quantity: \");\r\n    scanf(\"%d\", &i.quantity);\r\n\r\n    // Displaying output\r\n    printf(\"\\n----- Item Details -----\\n\");\r\n    printf(\"Item Code : %d\\n\", i.item_code);\r\n    printf(\"Item Name : %s\\n\", i.name);\r\n    printf(\"Quantity  : %d\\n\", i.quantity);\r\n\r\n    return 0;\r\n}',1,1,'2026-02-03 11:15:52','2026-02-03 11:16:39'),
(8,30,1,'#include <stdio.h>\r\n#include <string.h>\r\n\r\nint main()\r\n{\r\n    char name[5][20];\r\n    char surname[5][20];\r\n    char fullname[5][40];\r\n    int i;\r\n\r\n    // Input names\r\n    printf(\"Enter 5 Names:\\n\");\r\n    for(i = 0; i < 5; i++)\r\n    {\r\n        scanf(\"%s\", name[i]);\r\n    }\r\n\r\n    // Input surnames\r\n    printf(\"\\nEnter 5 Surnames:\\n\");\r\n    for(i = 0; i < 5; i++)\r\n    {\r\n        scanf(\"%s\", surname[i]);\r\n    }\r\n\r\n    // Concatenate name and surname\r\n    for(i = 0; i < 5; i++)\r\n    {\r\n        strcpy(fullname[i], name[i]);   // copy name\r\n        strcat(fullname[i], \" \");        // add space\r\n        strcat(fullname[i], surname[i]); // add surname\r\n    }\r\n\r\n    // Display full names\r\n    printf(\"\\n----- Full Names -----\\n\");\r\n    for(i = 0; i < 5; i++)\r\n    {\r\n        printf(\"%s\\n\", fullname[i]);\r\n    }\r\n\r\n    return 0;\r\n}',0,0,'2026-02-03 11:27:26','2026-02-03 11:27:26'),
(9,31,1,'#include <stdio.h>\n#include <math.h>\n\nint Armstrong(int num)\n{\n    int original = num, remainder, digits = 0;\n    int sum = 0, temp = num;\n\n    // Count number of digits\n    while (temp != 0)\n    {\n        digits++;\n        temp = temp / 10;\n    }\n\n    // Calculate Armstrong sum\n    temp = num;\n    while (temp != 0)\n    {\n        remainder = temp % 10;\n        sum = sum + pow(remainder, digits);\n        temp = temp / 10;\n    }\n\n    // Check Armstrong\n    if (sum == original)\n        return 1;\n    else\n        return 0;\n}\n\nint main()\n{\n    int n;\n\n    printf(\"Enter a number: \");\n    scanf(\"%d\", &n);\n\n    if (Armstrong(n))\n        printf(\"Armstrong Number\\n\");\n    else\n        printf(\"Not an Armstrong Number\\n\");\n\n    return 0;\n}',0,1,'2026-02-03 11:35:53','2026-02-03 11:36:09'),
(10,17,1,'import java.util.Scanner;\r\nclass Count_Upper_Lower {\r\n    public static void main(String[] args) {\r\n        Scanner scanner = new Scanner(System.in);\r\n        System.out.print(\"Enter a string: \");\r\n        String str = scanner.nextLine();\r\n        int upperCount = 0;\r\n        int lowerCount = 0;\r\n\r\n        for (int i = 0; i < str.length(); i++) {\r\n            char ch = str.charAt(i);\r\n            if (Character.isUpperCase(ch)) {\r\n                upperCount++;\r\n            } else if (Character.isLowerCase(ch)) {\r\n                lowerCount++;\r\n            }\r\n        }\r\n\r\n        System.out.println(\"Number of uppercase letters: \" + upperCount);\r\n        System.out.println(\"Number of lowercase letters: \" + lowerCount);\r\n    }\r\n}',0,1,'2026-02-09 07:19:53','2026-02-09 07:20:00'),
(11,18,1,'//WAP to accept multiple strings and arrange them in ascending order\r\nimport java.util.Scanner;\r\nimport java.util.Arrays;\r\n\r\nclass StringSort {\r\n    public static void main(String[] args) {\r\n\r\n        Scanner sc = new Scanner(System.in);\r\n\r\n        System.out.print(\"Enter number of strings: \");\r\n        int n = sc.nextInt();\r\n        sc.nextLine(); // clear buffer\r\n\r\n        String[] arr = new String[n];\r\n\r\n        System.out.println(\"Enter strings:\");\r\n        for (int i = 0; i < n; i++) {\r\n            arr[i] = sc.nextLine();\r\n        }\r\n\r\n        // Sorting strings in ascending order\r\n        Arrays.sort(arr);\r\n\r\n        System.out.println(\"\\nStrings in ascending order:\");\r\n        for (String s : arr) {\r\n            System.out.println(s);\r\n        }\r\n\r\n        sc.close();\r\n    }\r\n}',0,0,'2026-02-09 07:24:39','2026-02-09 07:24:39'),
(12,19,1,'import java.util.Scanner;\r\n\r\nclass StringRotation {\r\n    public static void main(String[] args) {\r\n\r\n        Scanner sc = new Scanner(System.in);\r\n\r\n        System.out.print(\"Enter a string: \");\r\n        String str = sc.nextLine();\r\n\r\n        int len = str.length();\r\n\r\n        System.out.println(\"All rotations of the string are:\");\r\n\r\n        for (int i = 0; i < len; i++) {\r\n            String rotation = str.substring(i) + str.substring(0, i);\r\n            System.out.println(rotation);\r\n        }\r\n\r\n        sc.close();\r\n    }\r\n}',0,1,'2026-02-09 07:32:39','2026-02-09 07:32:50'),
(13,20,1,'import java.util.Scanner;\r\nimport java.util.Arrays;\r\n\r\nclass AlphabeticalOrder {\r\n    public static void main(String[] args) {\r\n\r\n        Scanner sc = new Scanner(System.in);\r\n\r\n        System.out.print(\"Enter a string: \");\r\n        String str = sc.nextLine();\r\n\r\n        // Convert string to character array\r\n        char[] ch = str.toCharArray();\r\n\r\n        // Sort characters\r\n        Arrays.sort(ch);\r\n\r\n        // Convert back to string\r\n        String result = new String(ch);\r\n\r\n        System.out.println(\"Alphabetical order: \" + result);\r\n\r\n        sc.close();\r\n    }\r\n}',0,1,'2026-02-09 07:35:12','2026-02-09 07:35:17'),
(14,21,1,'class CheckUpper {\r\n    public static void main(String[] args) {\r\n\r\n        for (int i = 0; i < args.length; i++) {\r\n\r\n            String s = args[i];\r\n\r\n            // Check if string is uppercase\r\n            if (s.equals(s.toUpperCase())) {\r\n                System.out.println(s);\r\n            } else {\r\n                // Stop when lowercase string found\r\n                break;\r\n            }\r\n        }\r\n    }\r\n}',0,1,'2026-02-09 07:39:36','2026-02-09 07:39:41');
